import json

# Read the JSON file
with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Look at the structure
print("Keys at top level:", list(data.keys())[:20])

# Try to find yield data
def find_yields(d, path=""):
    if isinstance(d, dict):
        for k, v in d.items():
            find_yields(v, path + "." + k if path else k)
    elif isinstance(d, list) and len(d) > 0:
        if isinstance(d[0], dict):
            for item in d[:3]:
                find_yields(item, path)
        elif isinstance(d[0], (int, float)):
            print(f"{path}: {d[:10]}...")

# Look for yield-related tables
for key in data.keys():
    if 'yield' in key.lower() or 'ay' in key.lower() or 'average' in key.lower():
        print(f"\nFound key: {key}")
        if isinstance(data[key], list) and len(data[key]) > 0:
            print(f"  First item type: {type(data[key][0])}")
            if isinstance(data[key][0], dict):
                print(f"  Keys: {list(data[key][0].keys())[:10]}")
